// Design Tokens for Premium Expense Tracker
// Following Apple/Linear aesthetic principles

export const colors = {
  // Light Mode
  light: {
    background: '#f9f9f9',
    surface: '#ffffff',
    surfaceSecondary: '#f8fafc',
    textPrimary: '#111111',
    textSecondary: '#555555',
    textTertiary: '#888888',
    accent: '#2563eb',
    accentHover: '#1d4ed8',
    border: '#e5e7eb',
    borderLight: '#f1f5f9',
    success: '#10b981',
    error: '#ef4444',
    warning: '#f59e0b',
    shadow: 'rgba(0, 0, 0, 0.1)',
    shadowLight: 'rgba(0, 0, 0, 0.05)',
  },

  // Dark Mode
  dark: {
    background: '#0e0e0f',
    surface: '#18181b',
    surfaceSecondary: '#27272a',
    textPrimary: '#fafafa',
    textSecondary: '#a1a1aa',
    textTertiary: '#71717a',
    accent: '#60a5fa',
    accentHover: '#3b82f6',
    border: '#27272a',
    borderLight: '#3f3f46',
    success: '#34d399',
    error: '#f87171',
    warning: '#fbbf24',
    shadow: 'rgba(0, 0, 0, 0.3)',
    shadowLight: 'rgba(0, 0, 0, 0.2)',
  }
};

export const typography = {
  // Font Families
  fontFamily: {
    primary: ['Inter', 'system-ui', '-apple-system', 'sans-serif'],
    mono: ['JetBrains Mono', 'SF Mono', 'Monaco', 'monospace'],
  },

  // Font Sizes
  fontSize: {
    xs: '0.75rem',    // 12px
    sm: '0.875rem',   // 14px
    base: '1rem',     // 16px
    lg: '1.125rem',   // 18px
    xl: '1.25rem',    // 20px
    '2xl': '1.5rem',  // 24px
    '3xl': '1.875rem', // 30px
    '4xl': '2.25rem', // 36px
    '5xl': '3rem',    // 48px
  },

  // Font Weights
  fontWeight: {
    normal: 400,
    medium: 500,
    semibold: 600,
    bold: 700,
  },

  // Line Heights
  lineHeight: {
    tight: 1.25,
    normal: 1.5,
    relaxed: 1.625,
  },

  // Letter Spacing
  letterSpacing: {
    tight: '-0.025em',
    normal: '0em',
    wide: '0.025em',
    wider: '0.05em',
  }
};

export const spacing = {
  // Spacing Scale
  0: '0',
  1: '0.25rem',   // 4px
  2: '0.5rem',    // 8px
  3: '0.75rem',   // 12px
  4: '1rem',      // 16px
  5: '1.25rem',   // 20px
  6: '1.5rem',    // 24px
  8: '2rem',      // 32px
  10: '2.5rem',   // 40px
  12: '3rem',     // 48px
  16: '4rem',     // 64px
  20: '5rem',     // 80px
  24: '6rem',     // 96px
};

export const borderRadius = {
  none: '0',
  sm: '0.125rem',   // 2px
  base: '0.25rem',  // 4px
  md: '0.375rem',   // 6px
  lg: '0.5rem',     // 8px
  xl: '0.75rem',    // 12px
  '2xl': '1rem',    // 16px
  '3xl': '1.5rem',  // 24px
  full: '9999px',
};

export const shadows = {
  none: 'none',
  sm: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
  base: '0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06)',
  md: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)',
  lg: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)',
  xl: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)',
  '2xl': '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
};

export const transitions = {
  fast: '150ms cubic-bezier(0.4, 0, 0.2, 1)',
  normal: '300ms cubic-bezier(0.4, 0, 0.2, 1)',
  slow: '500ms cubic-bezier(0.4, 0, 0.2, 1)',
};

// Utility functions
export const getColor = (theme, colorKey) => colors[theme][colorKey];
export const getTypography = (key) => typography[key];
export const getSpacing = (key) => spacing[key];
export const getBorderRadius = (key) => borderRadius[key];
export const getShadow = (key) => shadows[key];
export const getTransition = (key) => transitions[key];

// Common component styles
export const buttonStyles = {
  base: `
    inline-flex items-center justify-center
    px-4 py-2
    text-sm font-medium
    border border-transparent
    rounded-md
    transition-colors duration-200
    focus:outline-none focus:ring-2 focus:ring-offset-2
    disabled:opacity-50 disabled:cursor-not-allowed
  `,
  variants: {
    primary: 'bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500',
    secondary: 'bg-gray-200 text-gray-900 hover:bg-gray-300 focus:ring-gray-500',
    ghost: 'text-gray-600 hover:text-gray-900 hover:bg-gray-100',
  }
};

export const inputStyles = {
  base: `
    block w-full
    px-3 py-2
    text-sm
    border border-gray-300
    rounded-md
    shadow-sm
    placeholder-gray-400
    focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500
    disabled:bg-gray-50 disabled:text-gray-500
  `
};

export const cardStyles = {
  base: `
    bg-white
    border border-gray-200
    rounded-lg
    shadow-sm
    transition-shadow duration-200
    hover:shadow-md
  `,
  variants: {
    elevated: 'shadow-lg hover:shadow-xl',
    flat: 'border-0 shadow-none',
  }
};
